CREATE OR REPLACE FUNCTION public.correct_vehicle_make_spelling() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE best record; second_distance integer; k text; BEGIN k=regexp_replace(lower(NEW.make),'[^a-z0-9]','','g'); IF length(k)<5 OR EXISTS(SELECT 1 FROM public.vehicle_name_catalog WHERE regexp_replace(lower(make),'[^a-z0-9]','','g')=k) OR EXISTS(SELECT 1 FROM public.vehicle_name_aliases WHERE make_input=lower(btrim(NEW.make))) THEN RETURN NEW; END IF; SELECT make,public.vehicle_name_distance(k,regexp_replace(lower(make),'[^a-z0-9]','','g')) d INTO best FROM (SELECT DISTINCT make FROM public.vehicle_name_catalog) m ORDER BY d,make LIMIT 1; IF best.d<=2 THEN SELECT min(public.vehicle_name_distance(k,regexp_replace(lower(make),'[^a-z0-9]','','g'))) INTO second_distance FROM public.vehicle_name_catalog WHERE make<>best.make; IF second_distance>=best.d+2 THEN NEW.make=best.make; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.correct_vehicle_make_spelling() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER a_correct_vehicle_make BEFORE INSERT OR UPDATE OF make,model ON public.vehicles FOR EACH ROW EXECUTE FUNCTION public.correct_vehicle_make_spelling();